def decimal_to_binary(decimal):
    """Converts a decimal number to binary representation with additional 'db' prefix and suffix."""
    if not isinstance(decimal, int):
        raise ValueError("Input must be an integer")

    if decimal == 0:
        return "db0db"  # Special case for zero

    bin_str = ""
    while decimal > 0:
        bin_str = str(decimal % 2) + bin_str
        decimal //= 2

    return f'db{bin_str}db'

def anti_shuffle(s):
    """
    Write a function that takes a string and returns an ordered version of it.
    Ordered version of string, is a string where all words (separated by space)
    are replaced by a new word where all the characters arranged in
    ascending order based on ascii value.
    Note: You should keep the order of words and blank spaces in the sentence.

    For example:
    anti_shuffle('Hi') returns 'Hi'
    anti_shuffle('hello') returns 'ehllo'
    anti_shuffle('Hello World!!!') returns 'Hello !!!Wdlor'
    """
    def sort_word(word):
        return ''.join(sorted(word))

    def anti_shuffle_helper(s):
        # Split the string into words
        words = s.split()
        # Sort each word and then join them back together with spaces
        return ' '.join([sort_word(word) for word in words])

    return anti_shuffle_helper(s)

