def unique_sublists(lst):
    """
    Count lists within a list. Return a dictionary where every list is converted to a tuple 
    and the value of such tuple is the number of its occurrences in the original list.

    :param lst: List of lists.
    :return: Dictionary mapping tuples from the sublists to their counts.
    """
    sublist_counts = {}
    for sublist in lst:
        # Convert list to tuple to ensure it's hashable and can be used as a key
        tup = tuple(sublist)
        if tup in sublist_counts:
            sublist_counts[tup] += 1
        else:
            sublist_counts[tup] = 1
    return sublist_counts

