    dp_up = [arr[i] for i in range(n)]
    dp_down = [arr[i] for i in range(n)]

    # Fill up the dp_up array
    for i in range(1, n):
        for j in range(i):
            if arr[j] < arr[i]:
                dp_up[i] = max(dp_up[i], dp_up[j] + arr[i])

