import math
def count_binary_seq(n):
    """
    Find the count of all binary sequences of length 2n such that sum of first n bits is same as sum of last n bits.

    :param n: Length of the binary sequence
    :return: Count of such binary sequences
    """
    if n == 0:
        return 0

    # Calculate the number of ways to choose k positions out of n for '1' (or '0')
    def binomial_coefficient(n, k):
        return math.comb(n, k)

    # The total number of sequences where the sum of the first n bits equals the sum of the last n bits is 
    # equal to the square of the binomial coefficient C(n/2, n/2) because each pair of positions can independently be either '0' or '1'
    count = binomial_coefficient(n // 2, n // 2)**2

    return int(count)

