def starts_one_ends(n):
    """
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
    """
    if n == 1:
        return 1  # Only one two-digit number (11)
    else:
        # For n > 1, calculate the total number of n-digit numbers starting or ending with 1
        # Total = (9 * 10^(n-2)) + (9 * 10^(n-1))
        # The first term counts numbers from 11 to 99 (9 possibilities per digit), 
        # and the second term counts numbers from 101 to 999 (9 possibilities per digit).
        return 9 * (10**(n-2)) + 9 * (10**(n-1))

