def lps(s):
    """
    Find the length of the longest palindromic subsequence in the given string.

    :param s: String to be processed
    :return: Length of the longest palindromic subsequence
    """
    n = len(s)
    dp = [[0] * n for _ in range(n)]

    # All single character substrings are palindromes of length 1
    for i in range(n):
        dp[i][i] = 1

    # Fill the table
    for cl in range(2, n + 1):
        for i in range(0, n - cl + 1):
            j = i + cl - 1
            if s[i] == s[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

    return dp[0][n - 1]

