def is_Monotonic(arr):
    increasing = decreasing = False
    for i in range(1, len(arr)):
        if arr[i] > arr[i - 1]:
            decreasing = True
        elif arr[i] < arr[i - 1]:
            increasing = True
        # If both increasing and decreasing conditions are met,
