def find_lucas(n):
    """
    Find the n-th Lucas number.

    :param n: The position of the Lucas number to be found
    :return: The n-th Lucas number
    """
    if n == 0:
        return 2
    elif n == 1:
        return 1
    else:
        a, b = 2, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b
